bool isMatchingBrackets(String s, char closingBracket) {
  if (s.isEmpty) return false;

  char lastChar = s[s.length - 1];

  switch (lastChar) {
    case '(':
      return closingBracket == ')';
    case '[':
      return closingBracket == ']';
    case '{':
      return closingBracket == '}';
    default:
      return false;
  }
}

