  List<String> binaryDigits = [];
  int remainder;

  while (decimal > 0) {
    remainder = decimal % 2;
    binaryDigits.add(remainder.toString());
    decimal ~/= 2;
  }

  // Reverse the digits to get the correct order
  binaryDigits = binaryDigits.reversed.toList();

  return binaryDigits.join('');
}

String decimalToBinary(int decimal) {
  if (decimal == 0) return '0';

  var binary = '';
  while (decimal > 0) {
    binary = (decimal % 2).toString() + binary;
    decimal ~/= 2;
  }

  return binary;
}

