String antiShuffle(String s) {
  if (s.length < 2) return s;

  final List<String> parts = [];
  int i = 0;
  while (i < s.length -1) {
    int j = i + 1;
    while (j < s.length && s[j] != ')') {
      j++;
    }

    String part = s.substring(i, j);
    if (part.isNotEmpty) {
      parts.add(part);
    }

    i = j + 1;
  }

  // Handle the last character
  if (i < s.length) {
    parts.add(s.substring(i));
  }

  var result = '';
  for (var i = 0; i < parts.length; i++) {
    var chunk = parts[i];
    if (chunk.contains('[')) {
      var splitChunk = chunk.split('[');
      var firstPart = splitChunk[0];
      var innerParts = splitChunk[1].split(']');

      var innerResult = '';
      for (var innerI = 0; innerI < innerParts.length; innerI++) {
        var innerChunk = innerParts[innerI];
        if (innerChunk.isEmpty || innerChunk == '') continue;

        if (innerChunk.contains('(')) {
          var innerSplit = innerChunk.split('(');
          var innerFirst = innerSplit[0];
          var innerInner = innerSplit[1].split(')');

          var innerFinal = '';
          for (var k = 0; k < innerInner.length; k++) {
            var innerSubChunk = innerInner[k];
            if (innerSubChunk.isEmpty) continue;

            var shuffleLength = min(innerSubChunk.length, 3); 
            var shuffled = _shuffleString(innerSubChunk, shuffleLength);
            innerFinal += shuffled;
          }
          innerResult += '$innerFirst$innerFinal';
        } else {
          innerResult += innerChunk;
        }
      }
      result += "$firstPart[$innerResult]";
    } else {
      result += chunk;
    }
  }

  return result;
}

String _shuffleString(String str, int length) {
  if (str.length <= length) return str;

  var chars = str.split('');
  var indices = List<int>.generate(length, (i) => i);
  Random random = Random();

  for (int i = indices.length - 1; i > 0; i--) {
    int j = random.nextInt(i + 1);
    var temp = indices[i];
    indices[i] = indices[j];
    indices[j] = temp;
  }

  var shuffledChars = chars.map((index) => chars[index]).toList();
  var shuffledStr = shuffledChars.take(length).join('');
  return shuffledStr;
}

