  bool hasLowercase = key.contains(RegExp('[a-z]'));

  if (hasUppercase && hasLowercase) {
    return key[0].toUpperCase() == key[0] && key.substring(1).toLowerCase() == key.substring(1);
  } else if (hasUppercase) {
    return key.toUpperCase() == key;
