bool _isCamelCase(String str) {
  if (str.isEmpty) return true; // assuming empty string is acceptable
  return RegExp(r'^[a-z][a-zA-Z0-9]*$').hasMatch(str);
}

bool _isSnakeCase(String str) {
  if (str.isEmpty) return true; // assuming empty string is acceptable
  return RegExp(r'^[a-z]+(_[a-z0-9]+)*$').hasMatch(str);
}

