// Helper function to recursively check the maximum value we can get from starting at [row][col]
int dfs(List<List<int>> grid, int row, int col, int rows, int cols, int cap) {
  if (row >= rows || col >= cols || row < 0 || col < 0 || grid[row][col] == 0) {
    return 0;
  }

  // If already visited this cell in this traversal, avoid cycles and infinite recursion
  if (grid[row][col] < 0) {
    return 0;
  }

  final currValue = grid[row][col];

  // We can't take it as part of any path that uses more than our capacity
  if (currValue > cap) {
    return 0;
  }

  // Marking as visited by setting to negative
  grid[row][col] *= -1;

  int left = dfs(grid, row + 1, col, rows, cols, cap - currValue); // down
  int right = dfs(grid, row - 1, col, rows, cols, cap - currValue); // up
  int top = dfs(grid, row, col + 1, rows, cols, cap - currValue); // right
  int bottom = dfs(grid, row, col - 1, rows, cols, cap - currValue); // left

  // Restore original value after backtracking
  grid[row][col] *= -1;

  return max(1 + max(left, right, top, bottom), max(left, right, top, bottom));
}

