      isPalindrome = false;
      break;
    }

    // Check if the first and last characters of the tokens match
    if (tokens[left][0] != tokens[right].last) {
      isPalindrome = false;
      break;
    }

    left++;
    right--;
  }

  return isPalindrome ? 'Yes' : 'No';
}

bool isPalindrome(String token) {
  int start = 0, end = token.length - 1;
  while (start < end) {
    if (token[start++] != token[end--]) {
      return false;
    }
  }
  return true;
}

